+
+            // Create 5 test notifications with different types
+            for ($i = 1; $i <= 5; $i++) {
+                $type = $types[($i - 1) % count($types)];
+                
+                $notification = $this->notificationService->createNotification(
+                    title: "Messenger Test Notification #{$i}",
