+                            "is working correctly with tenant isolation. Created at " . 
+                            (new \DateTimeImmutable())->format('Y-m-d H:i:s') . " for tenant '{$tenant->getName()}'.",
+                    type: $type,
+                    sendEmail: false,
+                    sendInApp: true,
+                    sendAsync: true
+                );
+
+                $notifications[] = $notification;
+            }
+
+            $this->addFlash('success', sprintf(
