\$kernel->boot();
\$container = \$kernel->getContainer();

\$entityManager = \$container->get(EntityManagerInterface::class);
\$tenantContext = \$container->get(TenantContextInterface::class);
\$notificationService = \$container->get(TenantNotificationService::class);

// Find the tenant
\$tenant = \$entityManager->getRepository(Tenant::class)->findOneBy(['slug' => 'acme-corp']);
if (!\$tenant) {
    echo 'Tenant not found\n';
    exit(1);
}

\$tenantContext->setTenant(\$tenant);

// Create an async notification
\$notification = \$notificationService->createNotification(
    title: 'Test Async Notification',
    message: 'This is a test async notification to verify the message handler works correctly.',
    type: 'info',
    recipientEmail: null,
    sendEmail: false,
    sendAsync: true
);

echo 'Created async notification with ID: ' . \$notification->getId() . \"\n\";
echo 'Status: ' . \$notification->getStatus() . \"\n\";
"

