@@ -0,0 +1,85 @@
+<?php
+
+declare(strict_types=1);
+
+namespace App\Command;
+
+use App\Entity\Tenant;
+use App\Service\TenantNotificationService;
+use Doctrine\ORM\EntityManagerInterface;
+use Symfony\Component\Console\Attribute\AsCommand;
+use Symfony\Component\Console\Command\Command;
+use Symfony\Component\Console\Input\InputArgument;
+use Symfony\Component\Console\Input\InputInterface;
+use Symfony\Component\Console\Output\OutputInterface;
+use Symfony\Component\Console\Style\SymfonyStyle;
+use Zhortein\MultiTenantBundle\Context\TenantContextInterface;
+
+/**
+ * Command to test async notification processing.
+ */
+#[AsCommand(
+    name: 'app:test-async-notification',
+    description: 'Test async notification processing with proper tenant context'
+)]
+final class TestAsyncNotificationCommand extends Command
+{
+    public function __construct(
+        private readonly EntityManagerInterface $entityManager,
+        private readonly TenantContextInterface $tenantContext,
+        private readonly TenantNotificationService $notificationService
+    ) {
+        parent::__construct();
+    }
+
+    protected function configure(): void
+    {
+        $this->addArgument('tenant-slug', InputArgument::REQUIRED, 'The tenant slug');
+    }
+
+    protected function execute(InputInterface $input, OutputInterface $output): int
+    {
+        $io = new SymfonyStyle($input, $output);
+        $tenantSlug = $input->getArgument('tenant-slug');
+
+        // Find the tenant
+        $tenant = $this->entityManager->getRepository(Tenant::class)
+            ->findOneBy(['slug' => $tenantSlug, 'active' => true]);
+
+        if (!$tenant) {
+            $io->error(sprintf('Tenant "%s" not found or inactive.', $tenantSlug));
+            return Command::FAILURE;
+        }
+
+        // Set tenant context
+        $this->tenantContext->setTenant($tenant);
+
+        $io->info(sprintf('Testing async notification for tenant: %s (%s)', $tenant->getName(), $tenant->getSlug()));
+
+        try {
+            // Create an async notification
+            $notification = $this->notificationService->createNotification(
+                title: 'Test Async Notification',
+                message: 'This is a test async notification to verify the message handler works correctly with the fixed tenant context.',
+                type: 'info',
+                recipientEmail: null,
+                sendEmail: false,
+                sendAsync: true
+            );
+
+            $io->success(sprintf(
+                'Created async notification with ID: %d, Status: %s',
+                $notification->getId(),
+                $notification->getStatus()
+            ));
+
+            $io->note('The notification has been queued for async processing. Run "php bin/console messenger:consume async" to process it.');
+
+            return Command::SUCCESS;
+
+        } catch (\Exception $e) {
+            $io->error(sprintf('Failed to create async notification: %s', $e->getMessage()));
+            return Command::FAILURE;
+        }
+    }
+}

content.text:
## Summary

I have successfully fixed the Symfony Messenger issue with the multi-tenant context. Here's what was resolved:

### ✅ **Issue Identified**

The error was occurring because the `SendNotificationMessageHandler` was trying to call a non-existent method:
```php
$this->tenantContext->setCurrentTenantBySlug($message->getTenantSlug());
```

The `TenantContextInterface` only provides:
- `setTenant(TenantInterface $tenant): void`
- `getTenant(): ?TenantInterface`
- `hasTenant(): bool`
- `clear(): void`

### ✅ **Fix Implemented**

**Updated `SendNotificationMessageHandler`**:

1. **Proper Tenant Resolution**:
   ```php
   // Find and set the tenant context for this message processing
   $tenant = $this->entityManager->getRepository(Tenant::class)
       ->findOneBy(['slug' => $message->getTenantSlug(), 'active' => true]);

   if (!$tenant) {
       $this->logger->error('Tenant not found for message processing', [
           'tenant_slug' => $message->getTenantSlug(),
           'notification_id' => $message->getNotificationId(),
       ]);
       return;
   }

   // Set the tenant context
   $this->tenantContext->setTenant($tenant);
   ```

2. **Enhanced Error Handling**:
   ```php
   // Try to mark notification as failed if it exists
   try {
       // Ensure tenant context is set for error handling
       if (!$this->tenantContext->hasTenant()) {
           $tenant = $this->entityManager->getRepository(Tenant::class)
               ->findOneBy(['slug' => $message->getTenantSlug(), 'active' => true]);
           if ($tenant) {
               $this->tenantContext->setTenant($tenant);
           }
       }
       // ... mark as failed logic
   } catch (\Exception $markFailedException) {
       // Log both original and mark-failed errors
   }
   ```

3. **Improved Logging**:
   - Added tenant ID to log messages
   - Enhanced error context
   - Separate error handling for marking notifications as failed

### ✅ **Testing Results**

**Successful Message Processing**:
```
10:58:15 INFO [messenger] Received message App\Message\SendNotificationMessage
10:58:15 INFO [app] Processing notification message ["notification_id" => 32, "tenant_slug" => "acme-corp", "tenant_id" => 1]
10:58:15 INFO [app] Notification processed successfully ["notification_id" => 32, "tenant_slug" => "acme-corp"]
10:58:15 INFO [messenger] Message App\Message\SendNotificationMessage handled successfully
```

**Queue Status**:
- ✅ Messages processed successfully
- ✅ No failed messages
- ✅ Queue empty after processing

### ✅ **Key Improvements**

1. **Correct API Usage**: Uses the proper `setTenant()` method with a `TenantInterface` object
2. **Robust Error Handling**: Handles both tenant resolution and notification processing errors
3. **Better Logging**: Provides detailed context for debugging
4. **Tenant Isolation**: Maintains proper tenant context during async processing
5. **Graceful Degradation**: Handles missing tenants without crashing

### ✅ **Technical Benefits**

- **Multi-tenant Safety**: Ensures proper tenant context in async processing
- **Error Resilience**: Gracefully handles various error scenarios
- **Debugging Support**: Comprehensive logging for troubleshooting
- **Performance**: Efficient tenant lookup and context setting
- **Maintainability**: Clean, well-documented code following Symfony best practices

