@@ -0,0 +1,209 @@
+<?php
+
+declare(strict_types=1);
+
+namespace App\Command;
+
+use App\Entity\Tenant;
+use App\Service\TenantMailerService;
+use App\Service\TenantNotificationService;
+use Doctrine\ORM\EntityManagerInterface;
+use Symfony\Component\Console\Attribute\AsCommand;
+use Symfony\Component\Console\Command\Command;
+use Symfony\Component\Console\Input\InputArgument;
+use Symfony\Component\Console\Input\InputInterface;
+use Symfony\Component\Console\Input\InputOption;
+use Symfony\Component\Console\Output\OutputInterface;
+use Symfony\Component\Console\Style\SymfonyStyle;
+use Zhortein\MultiTenantBundle\Context\TenantContextInterface;
+
+/**
+ * Command to test tenant-aware email functionality with Mailpit.
+ * 
+ * This command demonstrates how to send various types of emails
+ * in a multi-tenant context, allowing developers to test email
+ * functionality without actually sending emails to real recipients.
+ */
+#[AsCommand(
+    name: 'app:test-tenant-mailer',
+    description: 'Test tenant-aware email functionality with Mailpit'
+)]
+final class TestTenantMailerCommand extends Command
+{
+    public function __construct(
+        private readonly EntityManagerInterface $entityManager,
+        private readonly TenantContextInterface $tenantContext,
+        private readonly TenantMailerService $tenantMailer,
+        private readonly TenantNotificationService $notificationService
+    ) {
+        parent::__construct();
+    }
+
+    protected function configure(): void
+    {
+        $this
+            ->addArgument('tenant-slug', InputArgument::REQUIRED, 'The tenant slug')
+            ->addArgument('recipient-email', InputArgument::REQUIRED, 'The recipient email address')
+            ->addOption('test-type', 't', InputOption::VALUE_OPTIONAL, 'Type of test (simple|templated|notification|welcome|all)', 'all')
+            ->addOption('user-name', 'u', InputOption::VALUE_OPTIONAL, 'User name for welcome email', 'Test User')
+            ->setHelp(
+                'This command tests the tenant-aware email functionality by sending various types of emails to Mailpit.
+                
+Examples:
+  # Test all email types for acme-corp tenant
+  php bin/console app:test-tenant-mailer acme-corp test@example.com
+  
+  # Test only notification emails
+  php bin/console app:test-tenant-mailer acme-corp test@example.com --test-type=notification
+  
+  # Test welcome email with custom user name
+  php bin/console app:test-tenant-mailer acme-corp test@example.com --test-type=welcome --user-name="John Doe"
+  
+Available test types:
+  - simple: Simple text/HTML email
+  - templated: Custom templated email
+  - notification: Notification email (all types)
+  - welcome: Welcome email
+  - all: All email types (default)'
+            );
+    }
+
+    protected function execute(InputInterface $input, OutputInterface $output): int
+    {
+        $io = new SymfonyStyle($input, $output);
+        
+        $tenantSlug = $input->getArgument('tenant-slug');
+        $recipientEmail = $input->getArgument('recipient-email');
+        $testType = $input->getOption('test-type');
+        $userName = $input->getOption('user-name');
+
+        // Find the tenant
+        $tenant = $this->entityManager->getRepository(Tenant::class)
+            ->findOneBy(['slug' => $tenantSlug, 'active' => true]);
+
+        if (!$tenant) {
+            $io->error(sprintf('Tenant "%s" not found or inactive.', $tenantSlug));
+            return Command::FAILURE;
+        }
+
+        // Set tenant context
+        $this->tenantContext->setTenant($tenant);
+
+        $io->title('Testing Tenant-Aware Email Functionality');
+        $io->info(sprintf('Tenant: %s (%s)', $tenant->getName(), $tenant->getSlug()));
+        $io->info(sprintf('Recipient: %s', $recipientEmail));
+        $io->info(sprintf('Test Type: %s', $testType));
+        $io->newLine();
+
+        try {
+            $emailsSent = 0;
+
+            if ($testType === 'simple' || $testType === 'all') {
+                $io->section('Testing Simple Email');
+                $this->testSimpleEmail($recipientEmail, $tenant);
+                $emailsSent++;
+                $io->success('Simple email sent successfully');
+            }
+
+            if ($testType === 'templated' || $testType === 'all') {
+                $io->section('Testing Templated Email');
+                $this->testTemplatedEmail($recipientEmail, $tenant);
+                $emailsSent++;
+                $io->success('Templated email sent successfully');
+            }
+
+            if ($testType === 'notification' || $testType === 'all') {
+                $io->section('Testing Notification Emails');
+                $emailsSent += $this->testNotificationEmails($recipientEmail, $tenant);
+                $io->success('All notification emails sent successfully');
+            }
+
+            if ($testType === 'welcome' || $testType === 'all') {
+                $io->section('Testing Welcome Email');
+                $this->testWelcomeEmail($recipientEmail, $userName, $tenant);
+                $emailsSent++;
+                $io->success('Welcome email sent successfully');
+            }
+
+            $io->newLine();
+            $io->success(sprintf('All tests completed! %d emails sent to Mailpit.', $emailsSent));
+            $io->note([
+                'View the emails in Mailpit web interface:',
+                '• Open http://localhost:8025 in your browser',
+                '• Check the tenant-specific headers and branding',
+                '• Verify the email content and formatting',
+            ]);
+
+            return Command::SUCCESS;
+
+        } catch (\Exception $e) {
+            $io->error(sprintf('Failed to send test emails: %s', $e->getMessage()));
+            return Command::FAILURE;
+        }
+    }
+
+    private function testSimpleEmail(string $recipientEmail, Tenant $tenant): void
+    {
+        $this->tenantMailer->sendSimpleEmail(
+            to: $recipientEmail,
+            subject: 'Simple Email Test',
+            content: sprintf(
+                "Hello!\n\nThis is a simple email test for tenant %s.\n\nThis email demonstrates:\n- Tenant-specific from address\n- Tenant branding in HTML\n- Custom headers\n\nBest regards,\nThe %s Team",
+                $tenant->getName(),
+                $tenant->getName()
+            ),
+            tenant: $tenant
+        );
+    }
+
+    private function testTemplatedEmail(string $recipientEmail, Tenant $tenant): void
+    {
+        // Create a simple test template inline (in a real app, you'd use a proper template file)
+        $this->tenantMailer->sendTemplatedEmail(
+            to: $recipientEmail,
+            subject: 'Templated Email Test',
+            template: 'emails/notification.html.twig', // Reuse notification template for testing
+            context: [
+                'notification_title' => 'Templated Email Test',
+                'notification_message' => sprintf(
+                    'This is a templated email test for tenant %s. This demonstrates how to use Twig templates with tenant-specific context and branding.',
+                    $tenant->getName()
+                ),
+                'notification_type' => 'info',
+                'notification_icon' => '🧪',
+            ],
+            tenant: $tenant
+        );
+    }
+
+    private function testNotificationEmails(string $recipientEmail, Tenant $tenant): int
+    {
+        $notificationTypes = [
+            ['type' => 'info', 'title' => 'Information Notification', 'message' => 'This is an informational notification for testing purposes.'],
+            ['type' => 'success', 'title' => 'Success Notification', 'message' => 'This is a success notification indicating that an operation completed successfully.'],
+            ['type' => 'warning', 'title' => 'Warning Notification', 'message' => 'This is a warning notification that requires your attention.'],
+            ['type' => 'error', 'title' => 'Error Notification', 'message' => 'This is an error notification indicating that something went wrong and needs to be addressed.'],
+        ];
+
+        foreach ($notificationTypes as $notification) {
+            $this->tenantMailer->sendNotificationEmail(
+                to: $recipientEmail,
+                title: $notification['title'],
+                message: $notification['message'],
+                type: $notification['type'],
+                tenant: $tenant
+            );
+        }
+
+        return count($notificationTypes);
+    }
+
+    private function testWelcomeEmail(string $recipientEmail, string $userName, Tenant $tenant): void
+    {
+        $this->tenantMailer->sendWelcomeEmail(
+            to: $recipientEmail,
+            userName: $userName,
+            tenant: $tenant
+        );
+    }
+}

